  foreach(array_merge(['manage_digiforge_connections'],$caps)as $cap)if(!current_user_can($cap))return NativeFailure::error('order_response_authority');
  return get_current_user_id()===$actor&&is_user_logged_in()?true:NativeFailure::error('order_response_authority');
